// Shared data model used by both the generator (scripts/) and the site (src/).
// An Edition is one day's newspaper; it is serialised to
// src/content/editions/<date>.json by scripts/generate.ts.

export type Region = "india" | "global";

// A "further reading" link for a static-syllabus topic. Curated in
// config/syllabus.ts, never generated by the LLM, so every href is real.
// Only specific articles, books and official pages — no search-result links.
export type ReferenceKind = "official" | "wiki" | "report" | "book";

export interface Reference {
  label: string;
  href: string;
  kind: ReferenceKind;
}

export type Lean =
  | "official"
  | "centre"
  | "left"
  | "right"
  | "independent"
  | "global-north"
  | "global-south"
  | "regional"
  | "unknown";

export interface Article {
  id: string;
  title: string;
  link: string;
  source: string;
  sourceId: string;
  region: Region;
  categories: string[];
  publishedAt: string;
  snippet: string;
  // Position in the source's feed (0 = first, i.e. its front page). Used as a
  // cheap "importance" signal during selection.
  feedRank?: number;
}

export interface Perspective {
  source: string;
  region: string;
  lean: Lean;
  take: string;
  link: string;
  isRegional?: boolean;
}

export interface StaticLink {
  topic: string;
  paper: string;
  syllabusNode: string;
  whatIsIt: string;
  background: string;
  geography?: string;
  socioEconomic?: string;
  whyInNews: string;
  wayForward?: string;
  keyTerms: string[];
  prelimsPointers?: string[];
  mainsAngle?: string;
}

export interface Story {
  id: string;
  slug: string;
  headline: string;
  kicker: string;
  category: string;
  region: Region;
  importance: number;
  signal: "must-read" | "recommended" | "all";
  summary: string;
  whyItMatters: string;
  perspectives: Perspective[];
  articles: Article[];
  static: StaticLink[];
  prelims: string[];
  mainsQuestion?: string;
  tags: string[];
  readMinutes: number;
}

export interface OnThisDayItem {
  year: string;
  title: string;
  description: string;
  category: "event" | "birth" | "death" | "discovery";
  upscLink?: string;
}

// A lighter-weight item for the "Extras" reading list. Usually one article,
// but a cluster of articles covering the same event keeps all its source links.
export interface ExtraItem {
  title: string;
  date: string;
  articles: Article[];
}

// One row per feed we fetched for an edition: the display name, the feed URL
// itself (so a reader can open it and see the last ~24h of items), and how many
// in-window articles that feed contributed. Powers the page behind the edition's
// "N articles" stat, justifying where the articles came from — without storing
// every article URL.
export interface FeedStat {
  source: string;
  rss: string;
  count: number;
}

export interface Edition {
  date: string;
  generatedAt: string;
  windowStart: string;
  windowEnd: string;
  stats: { feeds: number; articles: number; stories: number };
  brief: string[];
  stories: Story[];
  onThisDay: OnThisDayItem[];
  // Lower-priority clusters + leftover articles — a safety net so nothing
  // important is missed. Older editions stored a flat Article[]; the site
  // normalises both shapes.
  extras?: ExtraItem[];
  // Per-feed article counts for the window. Optional: older editions predate it.
  feeds?: FeedStat[];
}

// One UPSC Prelims-style multiple-choice question. `answer` is a 0-based index
// into `options` (0 = A, 1 = B, 2 = C, 3 = D).
export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  answer: number;
  explanation: string;
  topic: string;
}

// A day's quiz. Generated by scripts/generate.ts alongside the edition and
// serialised to src/content/quizzes/<date>.json. Purely static: the site renders
// the questions and keeps the score in the browser session only.
export interface Quiz {
  date: string;
  generatedAt: string;
  title: string;
  // Coverage window of the editions the questions were drawn from.
  windowStart: string;
  windowEnd: string;
  questions: QuizQuestion[];
}

// ---- Static Editorial series ------------------------------------------------
// One day's long-form, teacher-narrated lesson from the common UPSC static
// syllabus. Generated by scripts/lib/staticSeries.ts and serialised to
// src/content/static-lessons/<date>.json. Kept out of edition.json so the daily
// edition stays small (see docs/storage-and-scaling.md).

export type StaticLessonSubjectKey =
  | "geography"
  | "polity"
  | "economy"
  | "history"
  | "environment"
  | "science"
  | "culture"
  | "society"
  | "ir"
  | "ethics"
  | "security";

export type StaticLessonBlock =
  | { type: "paragraph"; text: string }
  | { type: "heading"; text: string; level?: 3 | 4 }
  | { type: "callout"; title: string; text: string; tone?: "note" | "exam" | "anecdote" | "warning" }
  | { type: "list"; items: string[]; ordered?: boolean }
  | { type: "quote"; text: string; attribution?: string }
  | { type: "figure"; figureId: string };

export interface StaticLessonFigure {
  id: string;
  kind: "map" | "diagram" | "timeline" | "chart";
  title: string;
  caption: string;
  // Inline SVG only. The generator sanitises this before writing the file; no
  // external images are fetched, so lessons stay self-contained and fast.
  svg?: string;
  alt?: string;
  credit?: string;
}

export interface StaticLessonSection {
  heading: string;
  blocks: StaticLessonBlock[];
  // 1-based indexes into the lesson's references array, rendered as [n] links.
  refs?: number[];
}

export interface StaticLessonExam {
  prelims: string[];
  mains: string[];
  keyTerms: { term: string; meaning: string }[];
}

export interface StaticLessonHandoff {
  covered: string[];
  next: string;
  notes: string;
}

export interface StaticLessonSeries {
  subject: string;
  subjectKey: StaticLessonSubjectKey;
  paper: string;
  unitId: string;
  unitTitle: string;
  lessonId: string;
  lessonNumber: number;
  lessonCount: number;
  seriesLessonNumber: number;
  syllabusNode: string;
}

export interface StaticLesson {
  date: string;
  generatedAt: string;
  title: string;
  subtitle: string;
  readMinutes: number;
  hook: string;
  sections: StaticLessonSection[];
  figures: StaticLessonFigure[];
  anecdote?: { title: string; body: string };
  exam: StaticLessonExam;
  recap: string[];
  nextUp: string;
  references: Reference[];
  series: StaticLessonSeries;
  handoff: StaticLessonHandoff;
}

// Machine-readable progress through the static syllabus. Kept in
// data/static-series/progress.json so the plan itself (config/staticSeries.ts)
// stays a stable, human-editable curriculum and progress can be committed daily.
export interface StaticSeriesProgressEntry {
  lessonId: string;
  unitId: string;
  date: string;
}

export interface StaticSeriesProgress {
  version: 1;
  startedOn: string | null;
  updatedAt: string;
  completed: StaticSeriesProgressEntry[];
  current: { unitId: string; lessonId: string } | null;
  lastHandoff: (StaticLessonHandoff & { date: string; lessonId: string }) | null;
}
